import { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {
  const [name, setName] = useState("");
  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {
    const res = await axios.get("http://localhost:5000/api/queue/all");
    setQueues(res.data);
  };

  useEffect(() => {
    fetchQueues();
  }, []);

  const addQueue = async () => {
    await axios.post("http://localhost:5000/api/queue/add", {
      customerName: name
    });

    setName("");
    fetchQueues();
  };

  const updateStatus = async (id, status) => {
    await axios.put(`http://localhost:5000/api/queue/update/${id}`, {
      status
    });

    fetchQueues();
  };

  return (
    <div style={{ padding: "50px" }}>
      <h1>Smart Queue Dashboard</h1>

      <input
        type="text"
        placeholder="Customer Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />

      <button onClick={addQueue}>Generate Token</button>

      <hr />

      {queues.map((q) => (
        <div
          key={q._id}
          style={{
            border: "1px solid black",
            padding: "10px",
            marginBottom: "10px"
          }}
        >
          <h3>Token: {q.tokenNumber}</h3>
          <p>Name: {q.customerName}</p>
          <p>Status: {q.status}</p>

          <button
            onClick={() => updateStatus(q._id, "Completed")}
          >
            Complete
          </button>
        </div>
      ))}
    </div>
  );
}

export default Dashboard;
